package com.mygo.music;

import android.app.*;
import android.content.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;

/** The exact 5.47 control and current cache, real HTTP/files and native offline PCM. */
final class CacheConsistencyChecks {
 final Instrumentation test;final Context context;final CompletionChecks helper;final LiveAacChecks audio;
 CacheConsistencyChecks(Instrumentation test){this.test=test;context=test.getTargetContext();helper=new CompletionChecks(test);audio=new LiveAacChecks(test);}
 static void check(boolean yes,String message){if(!yes)throw new AssertionError(message);}
 interface Target {void store(String id,String url,JSONObject info,AudioCache.Callback callback);File find(String id);JSONObject info(String id);boolean busy();void clear();}
 final Map<String,String> headers=Collections.singletonMap("X-Cache-Key","fixture");
 Target fixed(AudioCache c){return new Target(){public void store(String id,String url,JSONObject i,AudioCache.Callback cb){c.store(id,"Cache consistency fixture","high",url,headers,i,cb);}public File find(String id){return c.find(id,"high");}public JSONObject info(String id){return c.metadata(id,"high");}public boolean busy(){return c.busy();}public void clear(){c.clear();}};}
 Target legacy(BaselineAudioCache c){return new Target(){public void store(String id,String url,JSONObject i,AudioCache.Callback cb){c.store(id,"Cache consistency fixture","high",url,headers,i,(ok,msg)->cb.done(ok,msg));}public File find(String id){return c.find(id,"high");}public JSONObject info(String id){return c.metadata(id,"high");}public boolean busy(){return c.busy();}public void clear(){c.clear();}};}
 static final class Answer {final CountDownLatch done=new CountDownLatch(1);volatile boolean ok;volatile String message="";void completed(boolean yes,String text){ok=yes;message=text;done.countDown();}boolean await()throws Exception{check(done.await(15,TimeUnit.SECONDS),"cache callback timed out");return ok;}}
 Answer store(Target cache,String id,String url,JSONObject info){Answer r=new Answer();cache.store(id,url,info,r::completed);return r;}
 final class Server implements AutoCloseable {
  final ServerSocket socket=new ServerSocket(0,12,InetAddress.getByName("127.0.0.1"));final ExecutorService workers=Executors.newCachedThreadPool();final byte[] aac=new NativeAudioChecks(test).asset("bilibili-stereo.m4a");final ConcurrentHashMap<String,AtomicInteger> requests=new ConcurrentHashMap<>();
  final CountDownLatch oldStarted=new CountDownLatch(1),newStarted=new CountDownLatch(1),releaseOld=new CountDownLatch(1),releaseNew=new CountDownLatch(1);volatile boolean badHeader;
  Server()throws Exception{Thread loop=new Thread(()->{while(!socket.isClosed())try{Socket client=socket.accept();workers.execute(()->serve(client));}catch(Exception ignored){}});loop.setDaemon(true);loop.start();}
  String base(){return "http://127.0.0.1:"+socket.getLocalPort();}int count(String path){AtomicInteger n=requests.get(path);return n==null?0:n.get();}
  void serve(Socket client){try(Socket active=client){active.setSoTimeout(5000);BufferedReader in=new BufferedReader(new InputStreamReader(active.getInputStream(),"US-ASCII"));String first=in.readLine(),line;if(first==null)return;boolean allowed=false;while((line=in.readLine())!=null&&!line.isEmpty())if(line.equalsIgnoreCase("X-Cache-Key: fixture"))allowed=true;badHeader|=!allowed;String path=first.split(" ")[1].split("\\?",2)[0];requests.computeIfAbsent(path,key->new AtomicInteger()).incrementAndGet();OutputStream out=active.getOutputStream();if(!allowed){out.write("HTTP/1.1 403 Denied\r\nContent-Length: 0\r\n\r\n".getBytes("US-ASCII"));return;}out.write(("HTTP/1.1 200 OK\r\nContent-Type: audio/mp4\r\nContent-Length: "+aac.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));if(path.equals("/old.m4a")||path.equals("/new.m4a")){out.write(aac,0,44);out.flush();boolean old=path.equals("/old.m4a");(old?oldStarted:newStarted).countDown();(old?releaseOld:releaseNew).await(15,TimeUnit.SECONDS);out.write(aac,44,aac.length-44);}else out.write(aac);out.flush();}catch(Exception ignored){}}
  public void close(){releaseOld.countDown();releaseNew.countDown();try{socket.close();}catch(Exception ignored){}workers.shutdownNow();}
 }
 JSONObject firstInfo()throws Exception{return new JSONObject().put("sourceCodec","aac").put("sourceQuality","high");}
 JSONObject nextInfo()throws Exception{return new JSONObject().put("sourceCodec","flac").put("sourceQuality","lossless");}
 JSONObject verify(Target cache,boolean baseline)throws Exception{
  String track="plugin://cache-consistency?id=original",retry="plugin://cache-consistency?id=retry";JSONObject report=new JSONObject().put("baseline",baseline);
  try(Server server=new Server()){
   check(store(cache,track,server.base()+"/audio.m4a",firstInfo()).await(),"initial complete cache failed");File original=cache.find(track);check(original!=null&&Arrays.equals(java.nio.file.Files.readAllBytes(original.toPath()),server.aac),"initial cache payload differs");check(cache.info(track).getString("sourceCodec").equals("aac"),"callback preceded metadata publication");check(store(cache,track,server.base()+"/not-fetched.flac",nextInfo()).await(),"cache reuse failed");boolean changed=cache.info(track).optString("sourceCodec").equals("flac");check(changed==baseline,"cache-hit information behavior differs from the expected control");check(server.count("/not-fetched.flac")==0&&server.count("/audio.m4a")==1&&Arrays.equals(java.nio.file.Files.readAllBytes(original.toPath()),server.aac),"cache hit downloaded or replaced audio");report.put("existingMetadataMatchesBytes",!changed).put("cacheHitDidNotDownload",true);
   // Retry before find() can remove the stale index.
   try(RandomAccessFile out=new RandomAccessFile(original,"rw")){out.setLength(44);}check(store(cache,track,server.base()+"/repair.m4a",firstInfo()).await(),"truncated cache retry failed");boolean repaired=original.length()==server.aac.length;check(repaired!=baseline,"truncated-entry behavior differs from the expected control");report.put("truncatedFileRefetched",repaired);
   if(!baseline){check(cache.info(track).getString("sourceCodec").equals("aac"),"repair metadata differs from payload");check(original.delete(),"could not remove fixture");check(store(cache,track,server.base()+"/missing.m4a",firstInfo()).await(),"missing file incorrectly reused");check(cache.find(track)!=null&&cache.info(track).optString("sourceCodec").equals("aac"),"missing entry not restored");report.put("missingFileRefetched",true);}
   cache.clear();Answer old=store(cache,retry,server.base()+"/old.m4a",firstInfo());check(server.oldStarted.await(5,TimeUnit.SECONDS),"old request did not enter held response");cache.clear();Answer fresh=store(cache,retry,server.base()+"/new.m4a",firstInfo());boolean early=fresh.done.await(180,TimeUnit.MILLISECONDS);check(early==baseline,"clear-and-submit differs from expected control");if(baseline)check(!fresh.ok,"baseline accepted same-key retry");else check(cache.busy(),"new generation not registered");server.releaseOld.countDown();check(!old.await(),"cancelled old cache was published");
   if(!baseline){check(server.newStarted.await(5,TimeUnit.SECONDS),"new cache job did not start");check(cache.busy(),"old cleanup removed current generation state");Answer duplicate=store(cache,retry,server.base()+"/duplicate.m4a",nextInfo());check(!duplicate.await()&&duplicate.message.contains("正在缓存"),"duplicate current transfer allowed");server.releaseNew.countDown();check(fresh.await(),"new generation failed");File saved=cache.find(retry);check(saved!=null&&Arrays.equals(java.nio.file.Files.readAllBytes(saved.toPath()),server.aac)&&cache.info(retry).optString("sourceCodec").equals("aac"),"fresh bytes and metadata disagree");check(server.count("/new.m4a")==1&&server.count("/duplicate.m4a")==0,"current transfer duplicated");report.put("newGenerationSurvivedOldCleanup",true).put("completeBytes",saved.length()).put("sourceHeadersRetained",!server.badHeader);}
   report.put("clearThenRetryAccepted",!early);check(!cache.busy(),"job state leaked");return report;
  }
 }
 void save(String name,JSONObject report)throws Exception{File folder=new File(context.getExternalFilesDir(null),"qa/cache-consistency");folder.mkdirs();try(OutputStream out=new FileOutputStream(new File(folder,name))){out.write(report.toString(2).getBytes("UTF-8"));}}
 void run()throws Exception{
  File directory=new File(context.getCacheDir(),"cache-547-negative-control");PluginArchive.delete(directory);BaselineAudioCache baseline=new BaselineAudioCache(directory,8*1024*1024);
  try{JSONObject before=verify(legacy(baseline),true);check(!before.getBoolean("existingMetadataMatchesBytes")&&!before.getBoolean("truncatedFileRefetched")&&!before.getBoolean("clearThenRetryAccepted"),"5.47 control did not reproduce defects");save("baseline.json",before);}finally{baseline.close();PluginArchive.delete(directory);}
  android.content.SharedPreferences prefs=context.getSharedPreferences("library",0);Map<String,?> old=new HashMap<>(prefs.getAll());prefs.edit().putBoolean("auto_cache",false).putString("player_theme","spectrum").putBoolean("player_remember_theme",true).putFloat("play_speed",1).commit();MainActivity activity=audio.launch();PlaybackService service=audio.service(activity);AudioCache cache=AudioCache.shared(context);ThemedPlayerDialog[] page={null};
  try{test.runOnMainSync(service::clearQueue);cache.clear();JSONObject report=verify(fixed(cache),false);String track="plugin://cache-consistency?id=retry";JSONObject expected=cache.metadata(track,"high");AudioCache reloaded=new AudioCache(new File(context.getNoBackupFilesDir(),"audio-cache"),AudioCache.DEFAULT_LIMIT);try{check(reloaded.find(track,"high")!=null&&reloaded.metadata(track,"high").optString("sourceCodec").equals(expected.optString("sourceCodec")),"metadata lost when reloaded");}finally{reloaded.close();}new HlsCacheChecks(test).offline(activity,cache,track,0);helper.await(()->service.snapshot().offlineOnly&&service.snapshot().stream.startsWith("file:")&&service.snapshot().position>500,"fixed cache did not play offline");page[0]=audio.capture(activity);helper.await(()->audio.audible()&&Math.abs(AudioAnalysis.frame().peakLeft-440)<60&&Math.abs(AudioAnalysis.frame().peakRight-880)<60,"fixed cache has no actual stereo PCM");check(service.snapshot().qualityInfo.toLowerCase(Locale.ROOT).contains("aac")&&!service.snapshot().qualityInfo.toLowerCase(Locale.ROOT).contains("flac"),"offline quality does not describe cached AAC");report.put("offlineOutput",audio.output()).put("offlineQualityInfo",service.snapshot().qualityInfo).put("sourceUnavailable",true).put("reloadMetadataPreserved",true);test.runOnMainSync(()->{service.pause();service.seek(10000);});helper.await(()->!service.snapshot().playing&&Math.abs(service.snapshot().position-10000)<600,"offline paused seek failed");test.runOnMainSync(service::resume);helper.await(()->service.snapshot().position>10300&&audio.audible(),"offline seek has no PCM");report.put("seekOutput",audio.output()).put("passed",true);save("fixed.json",report);
  }finally{test.runOnMainSync(()->{context.stopService(new Intent(context,PlayerAudioCaptureService.class));if(page[0]!=null)page[0].dismiss();service.clearQueue();activity.finish();});cache.clear();new TurntableLyricsChecks(test).restore(prefs,old);}
 }
}
